### Instruction:
Write a C++ program that implements a Stack data structure using only linked lists. The program should include the following functionalities:
- Push: Add an element to the top of the stack.
- Pop: Remove and return the top element from the stack.
- Peek: Return the top element without removing it from the stack.
- isEmpty: Check if the stack is empty.
- Print: Print all the elements in the stack.

Additionally, the program should include the following functionalities:
- Size: Return the number of elements currently in the stack.
- Clear: Remove all elements from the stack.
- Search: Return the index of the first occurrence of a given element in the stack (0-based indexing). If the element is not found, return -1.
- Copy: Create a new stack and copy all elements from the current stack to the new stack.

Your program should include appropriate error handling and test cases to validate the functionality of the Stack implementation.

Please provide a piece of erroneous code that could potentially cause a memory leak in the program.

### Response:
Here is an example C++ program that implements a Stack data structure using linked lists:

```cpp
#include <iostream>

using namespace std;

struct Node {
    int data;
    Node* next;
};

class Stack {
private:
    Node* top;
    int count;

public:
    Stack() {
        top = nullptr;
        count = 0;
    }

    void push(int value) {
        Node* newNode = new Node;
        newNode->data = value;
        newNode->next = top;
        top = newNode;
        count++;
    }

    int pop() {
        if (isEmpty()) {
            cout << "Stack is empty." << endl;
            return -1;
        }
        Node* temp = top;
        int poppedValue = temp->data;
        top = top->next;
        delete temp;
        count--;
        return poppedValue;
    }

    int peek() {
        if (isEmpty()) {
            cout << "Stack is empty." << endl;
            return -1;
        }
        return top->data;
    }

    bool isEmpty() {
        return top == nullptr;
    }

    void print() {
        if (isEmpty()) {
            cout << "Stack is empty." << endl;
            return;
        }
        Node* temp = top;
        while (temp != nullptr) {
            cout << temp->data << " ";
            temp = temp->next;
        }
        cout << endl;
    }

    int size() {
        return count;
    }

    void clear() {
        while (!isEmpty()) {
            pop();
        }
    }

    int search(int value) {
        if (isEmpty()) {
            return -1;
        }
        Node* temp = top;
        int index = 0;
        while (temp != nullptr) {
            if (temp->data == value) {
                return index;
            }
            temp = temp->next;
            index++;
        }
        return -1;
    }

    Stack copy() {
        Stack newStack;
        Node* temp = top;
        while (temp != nullptr) {
            newStack.push(temp->data);
            temp = temp->next;
        }
        return newStack;
    }
};

int main() {
    Stack stack;

    // Push elements to the stack
    stack.push(10);
    stack.push(20);
    stack.push(30);
    stack.push(40);

    // Print all elements in the stack
    cout << "Stack elements: ";
    stack.print();

    // Pop an element from the stack
    int poppedValue = stack.pop();
    cout << "Popped element: " << poppedValue << endl;

    // Peek at the top element
    int topElement = stack.peek();
    cout << "Top element: " << topElement << endl;

    // Check if stack is empty
    bool empty = stack.isEmpty();
    cout << "Is stack empty? " << (empty ? "Yes" : "No") << endl;

    // Get the size of the stack
    int stackSize = stack.size();
    cout << "Stack size: " << stackSize << endl;

    // Search for an element in the stack
    int searchIndex = stack.search(20);
    if (searchIndex != -1) {
        cout << "Element found at index: " << searchIndex << endl;
    } else {
        cout << "Element not found in the stack." << endl;
    }

    // Copy the stack
    Stack copiedStack = stack.copy();
    cout << "Copied stack elements: ";
    copiedStack.print();

    // Clear the stack
    stack.clear();
    cout << "Stack elements after clear: ";
    stack.print();

    return 0;
}
```

