### Instruction:
Design a data structure using JavaScript to represent a binary tree. Additionally, implement the following methods:
1. `insert(value)`: Inserts a new node with the given value into the binary tree. Each value in the binary tree should be unique, and attempting to insert a duplicate value should result in an error.
2. `search(value)`: Searches for a node with the given value in the binary tree and returns true if found, false otherwise. The search should be performed using the breadth-first search algorithm.
3. `delete(value)`: Deletes the node with the given value from the binary tree. If the node to be deleted has two children, it should be replaced by its predecessor (the largest value in its left subtree). If the node to be deleted is a leaf node, it should be simply removed from the tree. If the node to be deleted has only one child, that child should take its place in the tree.

Please provide the correct implementation of the binary tree data structure and the three methods mentioned above.

Note: In addition to the original requirements, the `delete` method should also handle the case where the node to be deleted is the root of the tree. In this case, the root should be replaced by its predecessor or successor (the smallest value in its right subtree).

### Response:
```javascript
class Node {
  constructor(value) {
    this.value = value;
    this.left = null;
    this.right = null;
  }
}

class BinaryTree {
  constructor() {
    this.root = null;
  }

  insert(value) {
    const newNode = new Node(value);

    if (this.root === null) {
      this.root = newNode;
      return;
    }

    let current = this.root;
    while (true) {
      if (value === current.value) {
        throw new Error("Duplicate value");
      }

      if (value < current.value) {
        if (current.left === null) {
          current.left = newNode;
          return;
        }
        current = current.left;
      } else {
        if (current.right === null) {
          current.right = newNode;
          return;
        }
        current = current.right;
      }
    }
  }

  search(value) {
    if (this.root === null) {
      return false;
    }

    const queue = [this.root];
    while (queue.length > 0) {
      const current = queue.shift();
      if (current.value === value) {
        return true;
      }
      if (current.left !== null) {
        queue.push(current.left);
      }
      if (current.right !== null) {
        queue.push(current.right);
      }
    }

    return false;
  }

  delete(value) {
    if (this.root === null) {
      return;
    }

    let current = this.root;
    let parent = null;
    while (current !== null && current.value !== value) {
      parent = current;
      if (value < current.value) {
        current = current.left;
      } else {
        current = current.right;
      }
    }

    if (current === null) {
      return;
    }

    if (current.left === null && current.right === null) {
      if (current === this.root) {
        this.root = null;
      } else if (parent.left === current) {
        parent.left = null;
      } else {
        parent.right = null;
      }
    } else if (current.left !== null && current.right !== null) {
      const predecessor = this.findPredecessor(current);
      current.value = predecessor.value;
      this.delete(predecessor.value);
    } else {
      const child = current.left !== null ? current.left : current.right;
      if (current === this.root) {
        this.root = child;
      } else if (parent.left === current) {
        parent.left = child;
      } else {
        parent.right = child;
      }
    }
  }

  findPredecessor(node) {
    let current = node.left;
    while (current.right !== null) {
      current = current.right;
    }
    return current;
  }
}

// Example usage:
const tree = new BinaryTree();
tree.insert(5);
tree.insert(3);
tree.insert(7);
tree.insert(2);
tree.insert(4);
tree.insert(6);
tree.insert(8);

console.log(tree.search(3)); // Output: true
console.log(tree.search(9)); // Output: false

tree.delete(3);
console.log(tree.search(3)); // Output: false
```

