```cpp
#include <iostream>

using namespace std;

struct Node {
    int data;
    Node* prev;
    Node* next;
};

class DoublyLinkedList {
private:
    Node* head;
    Node* tail;
    int length;

public:
    DoublyLinkedList() {
        head = nullptr;
        tail = nullptr;
        length = 0;
    }

    void insertAtBeginning(int value) {
        Node* newNode = new Node();
        newNode->data = value;
        newNode->prev = nullptr;
        newNode->next = head;

        if (head != nullptr) {
            head->prev = newNode;
        }

        head = newNode;

        if (tail == nullptr) {
            tail = newNode;
        }

        length++;
    }

    void deleteFromEnd() {
        if (tail == nullptr) {
            cout << "List is empty." << endl;
            return;
        }

        Node* nodeToDelete = tail;

        if (tail == head) {
            tail = nullptr;
            head = nullptr;
        } else {
            tail = tail->prev;
            tail->next = nullptr;
        }

        delete nodeToDelete;
        length--;
    }

    int findLength() {
        return length;
    }

    void reverseList() {
        Node* current = head;
        Node* temp = nullptr;

        while (current != nullptr) {
            temp = current->prev;
            current->prev = current->next;
            current->next = temp;
            current = current->prev;
        }

        if (temp != nullptr) {
            head = temp->prev;
        }
    }

    bool searchElement(int value) {
        Node* current = head;

        while (current != nullptr) {
            if (current->data == value) {
                return true;
            }

            current = current->next;
        }

        return false;
    }

    void insertAtEnd(int value) {
        Node* newNode = new Node();
        newNode->data = value;
        newNode->prev = tail;
        newNode->next = nullptr;

        if (tail != nullptr) {
            tail->next = newNode;
        }

        tail = newNode;

        if (head == nullptr) {
            head = newNode;
        }

        length++;
    }

    void deleteFromBeginning() {
        if (head == nullptr) {
            cout << "List is empty." << endl;
            return;
        }

        Node* nodeToDelete = head;

        if (head == tail) {
            head = nullptr;
            tail = nullptr;
        } else {
            head = head->next;
            head->prev = nullptr;
        }

        delete nodeToDelete;
        length--;
    }

    void insertAfterNode(int value, int key) {
        Node* current = head;

        while (current != nullptr) {
            if (current->data == key) {
                Node* newNode = new Node();
                newNode->data = value;
                newNode->prev = current;
                newNode->next = current->next;

                if (current->next != nullptr) {
                    current->next->prev = newNode;
                }

                current->next = newNode;

                if (current == tail) {
                    tail = newNode;
                }

                length++;
                return;
            }

            current = current->next;
        }

        cout << "Key not found." << endl;
    }

    void deleteNode(int value) {
        Node* current = head;

        while (current != nullptr) {
            if (current->data == value) {
                if (current == head) {
                    deleteFromBeginning();
                    return;
                } else if (current == tail) {
                    deleteFromEnd();
                    return;
                } else {
                    current->prev->next = current->next;
                    current->next->prev = current->prev;
                    delete current;
                    length--;
                    return;
                }
            }

            current = current->next;
        }

        cout << "Node not found." << endl;
    }

    bool isEmpty() {
        return head == nullptr;
    }

    void displayList() {
        Node* current = head;

        while (current != nullptr) {
            cout << current->data << " ";
            current = current->next;
        }

