        System.out.println("Is queue empty? " + queue.isEmpty());
        System.out.println("Is queue full? " + queue.isFull());
        System.out.println("Queue size: " + queue.getSize());
        System.out.println("Queue capacity: " + queue.getCapacity());

        queue.enqueue(10);
        queue.enqueue(20);
