### Instruction:
Write a C++ program to calculate the shortest path between two points in a weighted directed graph using Dijkstra's algorithm. The graph is represented by an adjacency matrix and each edge has a positive weight associated with it. The program should output the shortest path length and the sequence of vertices visited in the shortest path.

### Response:
```cpp
#include <iostream>
#include <vector>
#include <limits>

const int INF = std::numeric_limits<int>::max();

void dijkstra(const std::vector<std::vector<int>>& graph, int source, int destination) {
    int numVertices = graph.size();
    std::vector<int> dist(numVertices, INF);
    std::vector<bool> visited(numVertices, false);
    std::vector<int> prev(numVertices, -1);

    dist[source] = 0;

    for (int i = 0; i < numVertices - 1; ++i) {
        int minDist = INF;
        int minIndex = -1;

        for (int j = 0; j < numVertices; ++j) {
            if (!visited[j] && dist[j] < minDist) {
                minDist = dist[j];
                minIndex = j;
            }
        }

        visited[minIndex] = true;

        for (int j = 0; j < numVertices; ++j) {
            if (!visited[j] && graph[minIndex][j] && dist[minIndex] != INF && dist[minIndex] + graph[minIndex][j] < dist[j]) {
                dist[j] = dist[minIndex] + graph[minIndex][j];
                prev[j] = minIndex;
            }
        }
    }

    std::cout << "Shortest Path Length: " << dist[destination] << std::endl;

    std::vector<int> path;
    int currentVertex = destination;
    while (currentVertex != -1) {
        path.push_back(currentVertex);
        currentVertex = prev[currentVertex];
    }

    std::cout << "Sequence of Vertices Visited in the Shortest Path: ";
    for (int i = path.size() - 1; i >= 0; --i) {
        std::cout << path[i] << " ";
    }
}

int main() {
    int numVertices;
    std::cout << "Enter the number of vertices: ";
    std::cin >> numVertices;

    std::vector<std::vector<int>> graph(numVertices, std::vector<int>(numVertices, 0));

    std::cout << "Enter the adjacency matrix:\n";
    for (int i = 0; i < numVertices; ++i) {
