import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;
import java.util.Stack;

public class ScientificCalculator {

    private static List<String> history = new ArrayList<>();

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        while (true) {
            System.out.print("Enter an expression: ");
            String expression = scanner.nextLine();

            if (expression.equals("exit")) {
                break;
            }

            double result = evaluateExpression(expression);
            System.out.println("Result: " + result);

            history.add(expression + " = " + result);
        }

        System.out.println("Calculation history:");
        for (String entry : history) {
            System.out.println(entry);
        }
    }

    private static double evaluateExpression(String expression) {
        Stack<Double> operandStack = new Stack<>();
        Stack<Character> operatorStack = new Stack<>();

        expression = insertBlanks(expression);

        String[] tokens = expression.split(" ");

        for (String token : tokens) {
            if (token.length() == 0) {
                continue;
            } else if (token.charAt(0) == '+' || token.charAt(0) == '-') {
                while (!operatorStack.isEmpty() &&
                        (operatorStack.peek() == '+' || operatorStack.peek() == '-' ||
                                operatorStack.peek() == '*' || operatorStack.peek() == '/' ||
                                operatorStack.peek() == '^' || operatorStack.peek() == '√' ||
                                operatorStack.peek() == '!' || operatorStack.peek() == '(')) {
                    processOperator(operandStack, operatorStack);
                }

                operatorStack.push(token.charAt(0));
            } else if (token.charAt(0) == '*' || token.charAt(0) == '/') {
                while (!operatorStack.isEmpty() &&
                        (operatorStack.peek() == '*' || operatorStack.peek() == '/' ||
                                operatorStack.peek() == '^' || operatorStack.peek() == '√' ||
                                operatorStack.peek() == '!')) {
                    processOperator(operandStack, operatorStack);
                }

                operatorStack.push(token.charAt(0));
            } else if (token.charAt(0) == '^' || token.charAt(0) == '√' || token.charAt(0) == '!') {
                operatorStack.push(token.charAt(0));
            } else if (token.trim().charAt(0) == '(') {
                operatorStack.push('(');
            } else if (token.trim().charAt(0) == ')') {
                while (operatorStack.peek() != '(') {
                    processOperator(operandStack, operatorStack);
                }

                operatorStack.pop();
            } else {
                operandStack.push(Double.parseDouble(token));
            }
        }

        while (!operatorStack.isEmpty()) {
            processOperator(operandStack, operatorStack);
        }

        return operandStack.pop();
    }

    private static void processOperator(Stack<Double> operandStack, Stack<Character> operatorStack) {
        char operator = operatorStack.pop();
        double operand1 = operandStack.pop();
        double result = 0;

        switch (operator) {
            case '+':
                result = operandStack.pop() + operand1;
                break;
            case '-':
                result = operandStack.pop() - operand1;
                break;
            case '*':
                result = operandStack.pop() * operand1;
                break;
            case '/':
                result = operandStack.pop() / operand1;
                break;
            case '^':
                result = Math.pow(operandStack.pop(), operand1);
                break;
            case '√':
                result = Math.sqrt(operand1);
                break;
            case '!':
                result = factorial((int) operand1);
                break;
        }

        operandStack.push(result);
    }

    private static double factorial(int n) {
        if (n == 0 || n == 1) {
            return 1;
        } else {
            return n * factorial(n - 1);
        }
    }

    private static String insertBlanks(String s) {
        StringBuilder result = new StringBuilder();

        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '(' || s.charAt(i) == ')' || s.charAt(i) == '+' ||
                    s.charAt(i) == '-' || s.charAt(i) == '*' || s.charAt(i) == '/' ||
                    s.charAt(i) == '^' || s.charAt(i) == '√' || s.charAt(i) == '!') {
                result.append(" ").append(s.charAt(i)).append(" ");
            } else {
                result.append(s.charAt(i));
            }
        }

        return result.toString();
    }
}
```

This implementation supports basic arithmetic operations (+, -, *, /), as well as parentheses for grouping expressions. The input expression can include both positive and negative numbers, and floating-point numbers are handled as well. The calculator also provides a history feature that stores the previous calculations and allows the user to retrieve them.

