### Instruction:
Generate a valid C++ code to implement a doubly linked list with the following operations:
1. Insertion of a new node at the beginning of the list with time complexity O(1) and space complexity O(1).
2. Deletion of a node from the end of the list with time complexity O(1) and space complexity O(1).
3. Finding the length of the list with time complexity O(n) and space complexity O(1).
4. Reversing the list with time complexity O(n) and space complexity O(1).
5. Searching for a specific element in the list with time complexity O(n) and space complexity O(1).
6. Insertion of a new node at the end of the list with time complexity O(1) and space complexity O(1).
7. Deletion of a node from the beginning of the list with time complexity O(1) and space complexity O(1).
8. Insertion of a new node after a specific node in the list with time complexity O(1) and space complexity O(1).
9. Deletion of a specific node from the list with time complexity O(1) and space complexity O(1).
10. Checking if the list is empty with time complexity O(1) and space complexity O(1).

The code should handle all edge cases mentioned in the given test, as well as new edge cases such as inserting after a node that does not exist in the list and deleting a node that does not exist in the list.

### Response:
```cpp
#include <iostream>

using namespace std;

struct Node {
    int data;
    Node* prev;
    Node* next;
};

class DoublyLinkedList {
private:
    Node* head;
    Node* tail;
    int length;

public:
    DoublyLinkedList() {
        head = nullptr;
        tail = nullptr;
        length = 0;
    }

    void insertAtBeginning(int value) {
        Node* newNode = new Node();
        newNode->data = value;
        newNode->prev = nullptr;
        newNode->next = head;

        if (head != nullptr) {
            head->prev = newNode;
        }

        head = newNode;

        if (tail == nullptr) {
            tail = newNode;
        }

        length++;
    }

    void deleteFromEnd() {
        if (tail == nullptr) {
            cout << "List is empty." << endl;
            return;
        }

        Node* nodeToDelete = tail;

        if (tail == head) {
            tail = nullptr;
            head = nullptr;
        } else {
            tail = tail->prev;
            tail->next = nullptr;
        }

        delete nodeToDelete;
        length--;
    }

    int findLength() {
        return length;
    }

    void reverseList() {
        Node* current = head;
        Node* temp = nullptr;

        while (current != nullptr) {
            temp = current->prev;
            current->prev = current->next;
            current->next = temp;
            current = current->prev;
        }

        if (temp != nullptr) {
            head = temp->prev;
        }
    }

    bool searchElement(int value) {
        Node* current = head;

        while (current != nullptr) {
            if (current->data == value) {
                return true;
            }

            current = current->next;
        }

        return false;
    }

    void insertAtEnd(int value) {
        Node* newNode = new Node();
        newNode->data = value;
        newNode->prev = tail;
        newNode->next = nullptr;

        if (tail != nullptr) {
            tail->next = newNode;
        }

        tail = newNode;

        if (head == nullptr) {
            head = newNode;
        }

        length++;
    }

    void deleteFromBeginning() {
        if (head == nullptr) {
            cout << "List is empty." << endl;
            return;
        }

        Node* nodeToDelete = head;

        if (head == tail) {
            head = nullptr;
            tail = nullptr;
        } else {
            head = head->next;
            head->prev = nullptr;
        }

        delete nodeToDelete;
        length--;
    }

    void insertAfterNode(int value, int key) {
        Node* current = head;

        while (current != nullptr) {
            if (current->data == key) {
                Node* newNode = new Node();
                newNode->data = value;
                newNode->prev = current;
                newNode->next = current->next;

                if (current->next != nullptr) {
                    current->next->prev = newNode;
                }

                current->next = newNode;

                if (current == tail) {
                    tail = newNode;
                }

                length++;
                return;
            }

            current = current->next;
        }

        cout << "Key not found." << endl;
    }

    void deleteNode(int value) {
        Node* current = head;

        while (current != nullptr) {
            if (current->data == value) {
                if (current == head) {
                    deleteFromBeginning();
                    return;
                } else if (current == tail) {
                    deleteFromEnd();
                    return;
                } else {
                    current->prev->next = current->next;
                    current->next->prev = current->prev;
                    delete current;
                    length--;
                    return;
                }
            }

            current = current->next;
        }

        cout << "Node not found." << endl;
    }

    bool isEmpty() {
        return head == nullptr;
    }

    void displayList() {
        Node* current = head;

        while (current != nullptr) {
            cout << current->data << " ";
            current = current->next;
        }

        cout << endl;
    }
};

int main() {
    DoublyLinkedList list;

    // Insert at beginning
    list.insertAtBeginning(3);
    list.insertAtBeginning(2);
    list.insertAtBeginning(1);
    cout << "List after inserting at the beginning: ";
    list.displayList();

    // Delete from end
    list.deleteFromEnd();
    cout << "List after deleting from the end: ";
    list.displayList();

    // Length of list
    cout << "Length of list: " << list.findLength() << endl;

    // Reverse the list
    list.reverseList();
    cout << "List after reversing: ";
    list.displayList();

    // Search element
    cout << "Searching for element 2: ";
    cout << (list.searchElement(2) ? "Found" : "Not found") << endl;

    // Insert at end
    list.insertAtEnd(4);
    list.insertAtEnd(5);
    cout << "List after inserting at the end: ";
    list.displayList();

    // Delete from beginning
    list.deleteFromBeginning();
    cout << "List after deleting from the beginning: ";
    list.displayList();

    // Insert after node
    list.insertAfterNode(6, 4);
    cout << "List after inserting after node 4: ";
    list.displayList();

    // Delete node
    list.deleteNode(4);
    cout << "List after deleting node 4: ";
    list.displayList();

    // Check if list is empty
    cout << "Is list empty? " << (list.isEmpty() ? "Yes" : "No") << endl;

    return 0;
}
```

