2. `search(value)`: Searches for a node with the given value in the binary tree and returns true if found, false otherwise. The search should be performed using the breadth-first search algorithm.
3. `delete(value)`: Deletes the node with the given value from the binary tree. If the node to be deleted has two children, it should be replaced by its predecessor (the largest value in its left subtree). If the node to be deleted is a leaf node, it should be simply removed from the tree. If the node to be deleted has only one child, that child should take its place in the tree.

Please provide the correct implementation of the binary tree data structure and the three methods mentioned above.

### Response:
class Node {
  constructor(value) {
    this.value = value;
    this.left = null;
    this.right = null;
  }
}

class BinaryTree {
  constructor() {
    this.root = null;
  }

  insert(value) {
    if (this.root === null) {
      this.root = new Node(value);
    } else {
      this.insertNode(this.root, value);
    }
  }

  insertNode(node, value) {
    if (value < node.value) {
      if (node.left === null) {
        node.left = new Node(value);
      } else {
        this.insertNode(node.left, value);
      }
    } else if (value > node.value) {
      if (node.right === null) {
        node.right = new Node(value);
      } else {
        this.insertNode(node.right, value);
      }
    } else {
      throw new Error('Duplicate value');
    }
  }

  search(value) {
    if (this.root === null) {
      return false;
    }

    const queue = [this.root];
    while (queue.length > 0) {
      const node = queue.shift();

      if (node.value === value) {
        return true;
      }

      if (node.left !== null) {
        queue.push(node.left);
      }

      if (node.right !== null) {
        queue.push(node.right);
      }
    }

    return false;
  }

  delete(value) {
    if (this.root === null) {
      return;
    }

    this.root = this.deleteNode(this.root, value);
  }

  deleteNode(node, value) {
    if (node === null) {
      return null;
    }

    if (value < node.value) {
      node.left = this.deleteNode(node.left, value);
    } else if (value > node.value) {
      node.right = this.deleteNode(node.right, value);
    } else {
      if (node.left === null && node.right === null) {
        node = null;
      } else if (node.left === null) {
        node = node.right;
      } else if (node.right === null) {
        node = node.left;
      } else {
        const predecessor = this.findMax(node.left);
        node.value = predecessor.value;
        node.left = this.deleteNode(node.left, predecessor.value);
      }
    }

    return node;
  }

  findMax(node) {
    while (node.right !== null) {
      node = node.right;
    }
    return node;
  }
}

