        bst.insert(3);
        bst.insert(7);
        bst.insert(2);
        bst.insert(4);
        bst.insert(6);
        bst.insert(8);

        bst.traverseDFS(); // Output: 5 3 2 4 7 6 8

        int sum = bst.calculateSum();
        System.out.println(sum); // Output: 35
    }
}
