### Instruction:
Write a C++ program to calculate the shortest path between two points in a weighted directed graph using Dijkstra's algorithm. The graph is represented by an adjacency matrix and each edge has a positive weight associated with it. The program should output the shortest path length, the sequence of vertices visited in the shortest path, and the total number of vertices visited during the algorithm's execution. Additionally, the program should only use standard template library (STL) data structures for the implementation, without using any external libraries or frameworks.

### Response:
```cpp
#include <iostream>
#include <vector>
#include <queue>

#define INF 99999

using namespace std;

void dijkstra(vector<vector<int>>& graph, int start, int end) {
    int numVertices = graph.size();
    vector<int> distance(numVertices, INF);
    vector<bool> visited(numVertices, false);
    vector<int> path(numVertices, -1);

    distance[start] = 0;
    visited[start] = true;

    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq;
    pq.push(make_pair(0, start));

    while (!pq.empty()) {
        int u = pq.top().second;
        pq.pop();

        for (int v = 0; v < numVertices; ++v) {
            if (graph[u][v] != INF && !visited[v]) {
                int newDist = distance[u] + graph[u][v];
                if (newDist < distance[v]) {
                    distance[v] = newDist;
                    path[v] = u;
                    pq.push(make_pair(distance[v], v));
                }
            }
        }
        visited[u] = true;
    }

    cout << "Shortest path length: " << distance[end] << endl;
    cout << "Sequence of vertices visited in the shortest path: ";

    vector<int> shortestPath;
    int current = end;
    while (current != -1) {
        shortestPath.push_back(current);
        current = path[current];
    }
    for (int i = shortestPath.size() - 1; i >= 0; --i) {
        cout << shortestPath[i] << " ";
    }
    cout << endl;

    int numVisited = 0;
    for (bool v : visited) {
        if (v) {
            numVisited++;
        }
    }
    cout << "Total number of vertices visited: " << numVisited << endl;
}

int main() {
    int numVertices;
    cout << "Enter the number of vertices: ";
    cin >> numVertices;

    vector<vector<int>> graph(numVertices, vector<int>(numVertices, INF));

    int numEdges;
    cout << "Enter the number of edges: ";
    cin >> numEdges;

    cout << "Enter the edges and their weights:" << endl;
    for (int i = 0; i < numEdges; ++i) {
        int u, v, weight;
        cin >> u >> v >> weight;
        graph[u][v] = weight;
    }

    int start, end;
    cout << "Enter the start and end vertices: ";
    cin >> start >> end;

    dijkstra(graph, start, end);

    return 0;
}
```

